CREATE TABLE `activity_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `action` varchar(60) COLLATE utf8mb4_general_ci NOT NULL,
  `target_type` enum('user','floor','room','device','rule','override','auth','setting','sensor') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'setting',
  `target_id` bigint unsigned DEFAULT NULL,
  `floor_id` bigint unsigned DEFAULT NULL,
  `room_id` bigint unsigned DEFAULT NULL,
  `device_id` bigint unsigned DEFAULT NULL,
  `result` enum('success','failure') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'success',
  `source` enum('manual','automation','scheduler') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'manual',
  `details_json` json DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `activity_logs_floor_id_foreign` (`floor_id`),
  KEY `created_at` (`created_at`),
  KEY `user_id` (`user_id`),
  KEY `room_id` (`room_id`),
  KEY `device_id` (`device_id`),
  KEY `action` (`action`),
  KEY `target_type_target_id` (`target_type`,`target_id`),
  CONSTRAINT `activity_logs_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE RESTRICT ON UPDATE SET NULL,
  CONSTRAINT `activity_logs_floor_id_foreign` FOREIGN KEY (`floor_id`) REFERENCES `floors` (`id`) ON DELETE RESTRICT ON UPDATE SET NULL,
  CONSTRAINT `activity_logs_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE RESTRICT ON UPDATE SET NULL,
  CONSTRAINT `activity_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
