INSERT INTO `automation_rules` VALUES (1,'Hemat Energi Ruang Kosong','Jika suatu ruangan kosong selama 5 menit, ubah mode ke Standby dan matikan perangkat non-esensial yang memenuhi syarat, kecuali perangkat yang dilindungi override. Contoh simulasi — nonaktif sampai Admin mengaktifkannya.','vacant_duration',300,'{\"vacant_duration_minutes\": 5}','[{\"mode\": \"standby\", \"type\": \"set_room_mode\"}, {\"type\": \"turn_off\", \"target_device_types\": [\"ac\", \"ac_central\", \"light\", \"computer\", \"projector\", \"exhaust_fan\"]}]','{\"room_ids\": []}','{\"note\": \"Perangkat esensial dan override selalu dilindungi.\", \"protect_essential\": true, \"protect_overrides\": true}',0,1,NULL,'2026-10-09 10:24:46','2026-10-09 10:24:46');
/*!40000 ALTER TABLE `automation_rules` ENABLE KEYS */;
