--
-- Table structure for table `devices`
--

DROP TABLE IF EXISTS `devices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `devices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `room_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `device_type` enum('ac','ac_central','light','computer','projector','videotron','audio','exhaust_fan','studio_lighting','other') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'other',
  `control_capability` enum('controllable','monitor_only') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'controllable',
  `is_essential` tinyint(1) NOT NULL DEFAULT '0',
  `inventory_status` enum('needs_verification','verified') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'needs_verification',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `position_x` decimal(5,2) DEFAULT NULL,
  `position_y` decimal(5,2) DEFAULT NULL,
  `source` enum('simulation','iot') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'simulation',
  `archived_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `room_id` (`room_id`),
  KEY `device_type` (`device_type`),
  KEY `is_active` (`is_active`),
  KEY `idx_devices_room_position` (`room_id`,`position_x`),
  CONSTRAINT `devices_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `devices_chk_1` CHECK (((`position_x` is null) or ((`position_x` >= 0) and (`position_x` <= 100)))),
  CONSTRAINT `devices_chk_2` CHECK (((`position_y` is null) or ((`position_y` >= 0) and (`position_y` <= 100)))),
  CONSTRAINT `devices_chk_3` CHECK ((((`position_x` is null) and (`position_y` is null)) or ((`position_x` is not null) and (`position_y` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

