CREATE TABLE `rooms` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `floor_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `room_type` enum('closed','open_area') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'closed',
  `mode` enum('active','standby','inactive') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `occupancy` enum('occupied','vacant') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'vacant',
  `vacant_since` datetime DEFAULT NULL,
  `inventory_status` enum('needs_verification','verified') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'needs_verification',
  `floor_verification_status` enum('verified','needs_verification') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'needs_verification',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `archived_at` datetime DEFAULT NULL,
  `map_x` decimal(5,2) DEFAULT NULL,
  `map_y` decimal(5,2) DEFAULT NULL,
  `map_w` decimal(5,2) DEFAULT NULL,
  `map_h` decimal(5,2) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rooms_floor_name` (`floor_id`,`name`),
  KEY `floor_id` (`floor_id`),
  KEY `is_active` (`is_active`),
  KEY `occupancy` (`occupancy`),
  CONSTRAINT `rooms_floor_id_foreign` FOREIGN KEY (`floor_id`) REFERENCES `floors` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `rooms_chk_1` CHECK (((`map_x` is null) or ((`map_x` >= 0) and (`map_x` <= 100)))),
  CONSTRAINT `rooms_chk_2` CHECK (((`map_y` is null) or ((`map_y` >= 0) and (`map_y` <= 100)))),
  CONSTRAINT `rooms_chk_3` CHECK ((((`map_x` is null) and (`map_y` is null) and (`map_w` is null) and (`map_h` is null)) or (((`map_x` + `map_w`) <= 100) and ((`map_y` + `map_h`) <= 100) and (`map_w` > 0) and (`map_h` > 0))))
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
